In modern JavaScript (ES6+), you can use the import statement:

import { something } from './module.js';

Or import the entire module:

import * as module from './module.js';

function isEven(num) {
  return num % 2 === 0;
}

function findMax(arr) {
  return Math.max(...arr);
}

